using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using WordPicker.Data;
using WordPicker.Models;

namespace WordPicker.Controllers;

public class WordListsController : Controller
{
    private readonly ApplicationDbContext _context;

    public WordListsController(ApplicationDbContext context)
    {
        _context = context;
    }

    // GET: WordLists
    public async Task<IActionResult> Index()
    {
        var wordLists = await _context.WordLists
            .OrderByDescending(w => w.CreatedAt)
            .ToListAsync();
        return View(wordLists);
    }

    // GET: WordLists/Create
    public IActionResult Create()
    {
        return View();
    }

    // POST: WordLists/Create
    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Create([Bind("Name")] WordList wordList)
    {
        if (ModelState.IsValid)
        {
            wordList.CreatedAt = DateTime.UtcNow;
            wordList.UpdatedAt = DateTime.UtcNow;
            _context.WordLists.Add(wordList);
            await _context.SaveChangesAsync();
            return RedirectToAction(nameof(Index));
        }
        return View(wordList);
    }

    // GET: WordLists/Details/5
    public async Task<IActionResult> Details(int? id)
    {
        if (id == null)
        {
            return NotFound();
        }

        var wordList = await _context.WordLists
            .Include(w => w.Words)
            .FirstOrDefaultAsync(m => m.Id == id);

        if (wordList == null)
        {
            return NotFound();
        }

        return View(wordList);
    }

    // GET: WordLists/Delete/5
    public async Task<IActionResult> Delete(int? id)
    {
        if (id == null)
        {
            return NotFound();
        }

        var wordList = await _context.WordLists
            .FirstOrDefaultAsync(m => m.Id == id);

        if (wordList == null)
        {
            return NotFound();
        }

        return View(wordList);
    }

    // POST: WordLists/Delete/5
    [HttpPost, ActionName("Delete")]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> DeleteConfirmed(int id)
    {
        var wordList = await _context.WordLists.FindAsync(id);
        if (wordList != null)
        {
            _context.WordLists.Remove(wordList);
            await _context.SaveChangesAsync();
        }

        return RedirectToAction(nameof(Index));
    }
}

