    public void Index_WhenCalled_ReturnsViewWithWordLists()
    {
        // Arrange
        using var context = CreateContext();
        var controller = new WordListsController(context);

        // Act
        var result = controller.Index().Result as ViewResult;

        // Assert
        Assert.IsNotNull(result);
        Assert.IsInstanceOfType(result.Model, typeof(List<WordList>));
    }

    [TestMethod]
    [TestCategory(TestCategories.Unit)]
    public void Index_WhenWordListsExist_ReturnsSortedList()
    {
        // Arrange
        using var context = CreateContext();
        context.WordLists.Add(new WordList { Name = "First List", CreatedAt = DateTime.UtcNow.AddDays(-1) });
        context.WordLists.Add(new WordList { Name = "Second List", CreatedAt = DateTime.UtcNow });
        context.SaveChanges();

        var controller = new WordListsController(context);

        // Act
        var result = controller.Index().Result as ViewResult;
        var model = result?.Model as List<WordList>;

        // Assert
        Assert.IsNotNull(model);
        Assert.AreEqual(2, model.Count);
        Assert.AreEqual("Second List", model[0].Name);
        Assert.AreEqual("First List", model[1].Name);
    }
}

