using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;
using WordPicker.Data;
using WordPicker.Models;

namespace WordPicker.Pages.WordLists;

public class IndexModel : PageModel
{
    private readonly ApplicationDbContext _context;

    public IndexModel(ApplicationDbContext context)
    {
        _context = context;
    }

    public IList<WordList> WordLists { get; set; } = new List<WordList>();

    [BindProperty]
    public WordList NewWordList { get; set; } = new();

    public async Task OnGetAsync()
    {
        WordLists = await _context.WordLists
            .OrderByDescending(w => w.CreatedAt)
            .ToListAsync();
    }

    public async Task<IActionResult> OnPostAsync()
    {
        if (!ModelState.IsValid)
        {
            WordLists = await _context.WordLists
                .OrderByDescending(w => w.CreatedAt)
                .ToListAsync();
            return Page();
        }

        NewWordList.CreatedAt = DateTime.UtcNow;
        NewWordList.UpdatedAt = DateTime.UtcNow;
        _context.WordLists.Add(NewWordList);
        await _context.SaveChangesAsync();

        return RedirectToPage();
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;
using WordPicker.Data;
using WordPicker.Models;

namespace WordPicker.Pages.WordLists;

public class DetailsModel : PageModel
{
    private readonly ApplicationDbContext _context;

    public DetailsModel(ApplicationDbContext context)
    {
        _context = context;
    }

    public WordList? WordList { get; set; }

    [BindProperty]
    public string NewWord { get; set; } = string.Empty;

    public async Task<IActionResult> OnGetAsync(int? id)
    {
        if (id == null)
        {
            return NotFound();
        }

        WordList = await _context.WordLists
            .Include(w => w.Words.OrderBy(w => w.CreatedAt))
            .FirstOrDefaultAsync(m => m.Id == id);

        if (WordList == null)
        {
            return NotFound();
        }

        return Page();
    }

    public async Task<IActionResult> OnPostAddWordAsync(int id)
    {
        if (string.IsNullOrWhiteSpace(NewWord))
        {
            return RedirectToPage(new { id });
        }

        var existingWord = await _context.WordEntries
            .FirstOrDefaultAsync(w => w.WordListId == id && w.Value == NewWord);

        if (existingWord != null)
        {
            TempData["ErrorMessage"] = $"'{NewWord}' already exists in this list.";
            return RedirectToPage(new { id });
        }

        var wordEntry = new WordEntry
        {
            WordListId = id,
            Value = NewWord,
            CreatedAt = DateTime.UtcNow
        };

        _context.WordEntries.Add(wordEntry);
        await _context.SaveChangesAsync();

        return RedirectToPage(new { id });
    }

    public async Task<IActionResult> OnPostRemoveWordAsync(int id, int wordId)
    {
        var wordEntry = await _context.WordEntries
            .FirstOrDefaultAsync(w => w.Id == wordId && w.WordListId == id);

        if (wordEntry != null)
        {
            _context.WordEntries.Remove(wordEntry);
            await _context.SaveChangesAsync();
        }

        return RedirectToPage(new { id });
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;
using WordPicker.Data;
using WordPicker.Models;

namespace WordPicker.Pages.WordLists;

public class DeleteModel : PageModel
{
    private readonly ApplicationDbContext _context;

    public DeleteModel(ApplicationDbContext context)
    {
        _context = context;
    }

    public WordList? WordList { get; set; }

    public async Task<IActionResult> OnGetAsync(int? id)
    {
        if (id == null)
        {
            return NotFound();
        }

        WordList = await _context.WordLists
            .FirstOrDefaultAsync(m => m.Id == id);

        if (WordList == null)
        {
            return NotFound();
        }

        return Page();
    }

    public async Task<IActionResult> OnPostAsync(int? id)
    {
        if (id == null)
        {
            return NotFound();
        }

        var wordList = await _context.WordLists.FindAsync(id);
        if (wordList != null)
        {
            _context.WordLists.Remove(wordList);
            await _context.SaveChangesAsync();
        }

        return RedirectToPage("./Index");
    }
}

